cypress_script:
describe('Add/Remove Elements Tests', () => {
  it('should add an element when the Add Element button is clicked', () => {
    cy.visit('https://the-internet.herokuapp.com/add_remove_elements/');
    cy.get('button').contains('Add Element').click();
    cy.get('#elements').children().should('have.length', 1);
    cy.url().should('eq', 'https://the-internet.herokuapp.com/add_remove_elements/');
  });

  it('should not add multiple elements when the Add Element button is not clicked', () => {
    cy.visit('https://the-internet.herokuapp.com/add_remove_elements/');
    cy.get('#elements').children().should('have.length', 0);
    cy.url().should('eq', 'https://the-internet.herokuapp.com/add_remove_elements/');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Add/Remove Elements Tests', () => {
  test('should add an element when the Add Element button is clicked', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/add_remove_elements/');
    await page.click('button:has-text("Add Element")');
    const elementsCount = await page.locator('#elements').count();
    expect(elementsCount).toBe(1);
    expect(page.url()).toBe('https://the-internet.herokuapp.com/add_remove_elements/');
  });

  test('should not add multiple elements when the Add Element button is not clicked', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/add_remove_elements/');
    const elementsCount = await page.locator('#elements').count();
    expect(elementsCount).toBe(0);
    expect(page.url()).toBe('https://the-internet.herokuapp.com/add_remove_elements/');
  });
});
